import unittest

import mylib as m


class T(unittest.TestCase):
    def test_unique_sorted_hidden(self):
        self.assertEqual(m.unique_sorted([]), [])
        self.assertEqual(m.unique_sorted([5, 5]), [5])

    def test_count_vowels_hidden(self):
        self.assertEqual(m.count_vowels(''), 0)
        self.assertEqual(m.count_vowels('xyz'), 0)

    def test_factorial_hidden(self):
        self.assertEqual(m.factorial(0), 1)
        self.assertEqual(m.factorial(6), 720)

    def test_first_n_hidden(self):
        self.assertEqual(m.first_n([1, 2], 5), [1, 2])
        self.assertEqual(m.first_n([1, 2, 3], 0), [])


if __name__ == '__main__':
    unittest.main()
